export type DisputeInput = { "action_required": boolean; "amount_money": MoneyValueInput; "case_type": "inquiry" | "chargeback" | "compliance" | "resolution" | "block" | "other" | "bank_return"; /** RFC3339 timestamp. Format: date-time. */ "created_at": string | globalThis.Date; "customer"?: (({ /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string | globalThis.Date; "customer_id": string; "email": string; "name"?: string; "phone"?: string; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string | globalThis.Date; }) | (null)); "customer_id"?: string; "dispute_id": string; "evidence_deadline_passed": boolean; /** RFC3339 timestamp. Format: date-time. */ "evidence_due_at"?: string | globalThis.Date | null; "evidence_response_allowed": boolean; /** Format: int32. */ "evidence_submission_count": number; "evidence_submission_past_due": boolean; "fraud_warning_id"?: string; /** Whether the provider reports evidence for this dispute, submitted or not. If evidence_submission_count is 0, no submission is recorded. */ "has_evidence": boolean; "merchant_id": string; "metadata": Record<string, string>; "order"?: (({ /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string | globalThis.Date; "customer_id"?: string; "fulfillment_status"?: "not_fulfilled" | "partially_fulfilled" | "fulfilled" | "canceled" | "not_applicable" | "closed"; "order_id": string; "order_number"?: string; "payment_intent_ids"?: Array<string>; "payment_status": "unpaid" | "partially_paid" | "paid"; "pricing_amounts": PricingAmountsInput; "refund_status": "none" | "partially_refunded" | "refunded"; "settlement_amounts": SettlementAmountsInput; "status": "open" | "closed"; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string | globalThis.Date; }) | (null)); "order_id"?: string; "payment_intent"?: (({ "amount_money": MoneyValueInput; "capture_method"?: "automatic" | "manual"; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string | globalThis.Date; "customer_id"?: string; "order_id"?: string; "payment_intent_id": string; "payment_source"?: PaymentSourceSummaryInput; "refund_status"?: "none" | "partially_refunded" | "refunded"; "status": "requires_payment_method" | "requires_confirmation" | "requires_action" | "processing" | "requires_capture" | "canceled" | "succeeded" | "expired"; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string | globalThis.Date; }) | (null)); "payment_intent_id"?: string; "payment_option"?: "card" | "apple_pay" | "google_pay" | "affirm" | "ach_debit" | null; "reason": "bank_cannot_process" | "check_returned" | "credit_not_processed" | "customer_initiated" | "debit_not_authorized" | "duplicate" | "fraudulent" | "general" | "incorrect_account_details" | "insufficient_funds" | "noncompliant" | "product_not_received" | "product_unacceptable" | "subscription_canceled" | "unrecognized" | "bank_account_closed" | "bank_account_not_found" | "bank_debit_not_authorized" | "bank_account_restricted" | "other"; /** Why a response is unavailable when evidence_response_allowed is false. Absent when no reason is reported. Current values are bank_return_not_contestable and provider_response_unavailable. The provider value means no evidence deadline was supplied; it does not identify why the provider cannot accept a response. */ "response_unavailable_reason"?: "bank_return_not_contestable" | "provider_response_unavailable"; "status": "warning_needs_response" | "warning_under_review" | "warning_closed" | "needs_response" | "under_review" | "won" | "lost" | "prevented"; /** Recorded time of the current status. On first observation this is the dispute creation time. Later status changes use the provider event time when available, or the time Flint observed the change. This may not be the exact decision or submission time. Format: date-time. */ "status_changed_at"?: string | globalThis.Date; /** RFC3339 timestamp. Format: date-time. */ "updated_at": string | globalThis.Date; };
